package io.github.diodeme.ji.acp.v2.preview;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;

class AcpV2PreviewCodecTest {
    private final AcpV2PreviewCodec codec = new AcpV2PreviewCodec(64, 1024 * 1024);

    @Test
    void encodesReplayStateAndStructuredDiffWithoutStableCoreTypes() {
        assertTrue(codec.replayFrom(codec.read("{\"type\":\"start\"}")) instanceof AcpV2PreviewModel.ReplayFrom.Start);
        var state = codec.stateUpdate("session-1", new AcpV2PreviewModel.StateUpdate.Idle(Optional.of("end_turn")));
        assertEquals("state_update", ((java.util.Map<?, ?>) state.get("update")).get("sessionUpdate"));
        var diff = new AcpV2PreviewModel.StructuredDiff(List.of(
                new AcpV2PreviewModel.Change(AcpV2PreviewModel.Operation.MOVE,
                        "C:\\old.txt", "C:\\new.txt", "text", "text/plain")),
                Optional.of(new AcpV2PreviewModel.Patch("git_patch", "diff --git a/old.txt b/new.txt")));
        String encoded = codec.write(codec.diff(diff));
        assertTrue(encoded.contains("\"oldPath\":\"C:/old.txt\""));
        assertTrue(encoded.contains("\"path\":\"C:/new.txt\""));
    }

    @Test
    void rejectsUnknownReplayAndInvalidMove() {
        assertThrows(IllegalArgumentException.class, () -> codec.replayFrom(codec.read("{\"type\":\"cursor\"}")));
        assertThrows(IllegalArgumentException.class, () -> new AcpV2PreviewModel.Change(
                AcpV2PreviewModel.Operation.MOVE, null, "/new", null, null));
    }
}
